#!/bin/bash
# Generated by llmd for agent task execution.
# This wrapper runs the agent and handles task lifecycle:
#   1. Runs the agent command
#   2. On exit, checks if the task was already moved (by hooks)
#   3. If not, moves the task based on exit code using rule transitions
#   4. Records run completion (stats, cost, tokens)
#
# Transport: HTTP API first (if LLMD_URL is set), CLI fallback.
# Template variables are replaced by llmd at spawn time.

TASK_ID="{{.TaskID}}"
AGENT="{{.Agent}}"
ROLE="{{.Role}}"
LLMD="{{.LLMD}}"
LLMD_URL="{{.URL}}"
PROJECT_DIR="{{.ProjectDir}}"
WORKTREE="{{.Worktree}}"

# Transitions from the rule. Always set at spawn time.
ON_SUCCESS="{{.OnSuccess}}"
ON_FAILURE="{{.OnFailure}}"

# task_move moves a task to the given column. Tries HTTP then CLI.
task_move() {
  local col="$1"
  if [ -z "${col}" ]; then
    return 0
  fi
  if [ -n "${LLMD_URL}" ]; then
    curl -sf -X POST "${LLMD_URL}/task/move/${TASK_ID}/${col}" \
      -H "Author: ${AGENT}" 2>/dev/null && return 0
  fi
  (cd "${PROJECT_DIR}" && "${LLMD}" --author "${AGENT}" task move "${TASK_ID}" "${col}") 2>/dev/null
}

# agent_complete records run completion with stats extracted from
# the agent's output log.
agent_complete() {
  local exit_code="$1"
  (cd "${PROJECT_DIR}" && "${LLMD}" --author "${AGENT}" agent complete "${TASK_ID}" --exit-code "${exit_code}") 2>/dev/null
}

# Run the agent.
cd "${WORKTREE}"
{{.Command}} {{.Args}}
EXIT=$?

# Record run completion first so the pipeline handler sees this run
# as finished when the task move triggers the next step.
agent_complete ${EXIT}

# On failure, capture the agent's last output as an audit note so
# the human reviewing the blocked task can see what went wrong.
if [ ${EXIT} -ne 0 ]; then
  LOG_FILE="${WORKTREE}/.llmd-agent.log"
  if [ -f "${LOG_FILE}" ]; then
    LAST_OUTPUT=$(tail -10 "${LOG_FILE}" 2>/dev/null | head -c 1000)
    if [ -n "${LAST_OUTPUT}" ]; then
      (cd "${PROJECT_DIR}" && "${LLMD}" --author "${AGENT}" audit add "${TASK_ID}" "${LAST_OUTPUT}") 2>/dev/null || true
    fi
  fi
fi

# Move the task based on exit code. All roles get automatic moves
# driven by the rule's success/failure transitions.
if [ ${EXIT} -eq 0 ]; then
  task_move "${ON_SUCCESS}" || true
else
  task_move "${ON_FAILURE}" || true
fi

exit ${EXIT}
